using System;
using UnityEngine;

namespace Halazia.Shared.Movement
{
    /// <summary>
    /// Core decoupling contract between AI decision/pathfinding logic (IS) and visual movement execution (Graphics).
    /// AI agents calculate paths and intentions; the implementing motor executes smooth translation, rotation, and physics.
    /// </summary>
    public interface IAgentMotor
    {
        /// <summary>
        /// Supplies an array of world-space waypoints for the motor to follow.
        /// </summary>
        /// <param name="waypoints">Ordered array of waypoints (e.g. generated by NavMesh.CalculatePath).</param>
        void SetPath(Vector3[] waypoints);

        /// <summary>
        /// Commands the agent to look toward a dynamic transform (e.g. player during combat) while moving.
        /// Pass null to restore natural movement-facing rotation.
        /// </summary>
        void SetFaceTarget(Transform target);

        /// <summary>
        /// Commands the agent to look toward a specific world position while moving.
        /// Pass null to restore natural movement-facing rotation.
        /// </summary>
        void SetFaceTarget(Vector3? worldPosition);

        /// <summary>
        /// Immediately ceases movement, clears current path, and brings the agent to a controlled stop.
        /// </summary>
        void Stop();

        /// <summary>
        /// Locks or unlocks forward translation (e.g. during attack animations or stagger) without clearing the path.
        /// </summary>
        void SetMovementLocked(bool locked);

        /// <summary>
        /// Temporarily scales movement speed (e.g. 0.5f while aiming or strafing, 1.0f for normal cruising).
        /// </summary>
        void SetSpeedModifier(float multiplier);

        /// <summary>
        /// True if forward movement is currently locked (e.g. during an attack animation).
        /// </summary>
        bool IsMovementLocked { get; }

        /// <summary>
        /// True if the agent is actively following a path towards a destination.
        /// </summary>
        bool IsMoving { get; }

        /// <summary>
        /// Current 3D velocity vector of the agent (m/s).
        /// </summary>
        Vector3 Velocity { get; }

        /// <summary>
        /// Current scalar horizontal speed (m/s).
        /// </summary>
        float CurrentSpeed { get; }

        /// <summary>
        /// Final world position destination of the current active path.
        /// </summary>
        Vector3 TargetDestination { get; }

        /// <summary>
        /// Triggered when the agent successfully reaches the final waypoint within stopping tolerance.
        /// </summary>
        event Action OnArrived;

        /// <summary>
        /// Triggered when the agent detects physical blockage, dynamic obstruction, or lack of progress.
        /// </summary>
        event Action OnPathBlocked;
    }
}
